import{_ as e,o as a,c as r,a5 as o}from"./chunks/framework.bIR-4glx.js";const u=JSON.parse('{"title":"从真实问题到首批用户：用访谈、人工试点与付费证据检验创业想法","description":"从最近一次真实任务出发，记录替代方案、反证和购买阻力，用有限的人工试点与两周实验判断创业想法该继续、调整还是停止。","frontmatter":{"title":"从真实问题到首批用户：用访谈、人工试点与付费证据检验创业想法","description":"从最近一次真实任务出发，记录替代方案、反证和购买阻力，用有限的人工试点与两周实验判断创业想法该继续、调整还是停止。","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"threads/practice/customer-discovery.md","filePath":"threads/practice/customer-discovery.md","lastUpdated":1789776000000}'),s={name:"threads/practice/customer-discovery.md"};function i(l,t,d,n,p,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="从真实问题到首批用户" tabindex="-1">从真实问题到首批用户 <a class="header-anchor" href="#从真实问题到首批用户" aria-label="Permalink to &quot;从真实问题到首批用户&quot;">​</a></h1><p>一个创业想法可以先写成一句可被推翻的话：<strong>哪一类人，在什么情境下，反复遇到什么问题，正在付出什么代价，愿意为怎样的结果改变做法？</strong> 如果这句话还写不清，先做调查比先做完整产品更容易找到下一步。</p><p><a href="./../part-2/entrepreneurship">创业篇</a> 记录了作者的经历，<a href="./../part-3/2-ai-development-and-resource-layer">AI 学习、项目开发与资源层创业</a> 讨论技术与交付边界。本页为它们补充用户验证的实操流程，<a href="./sustainable-business">可持续的小生意</a> 接着检查交付与经营，供读者按自己的情境调整。下面的步骤、数量和门槛是本指南的建议，案例均为假设，不是研究结论，也不能由几个访谈推断整个市场。</p><h2 id="_1-缩小到一次任务" tabindex="-1">1. 缩小到一次任务 <a class="header-anchor" href="#_1-缩小到一次任务" aria-label="Permalink to &quot;1. 缩小到一次任务&quot;">​</a></h2><p>“帮助小企业使用 AI”还不足以指导行动。可以缩小为：“每周更新商品介绍的小店经营者，需要把自己已确认的信息整理为发布草稿，目前逐项复制，经常漏掉规格。”这里有一个人、一项任务、一种既有做法和一个可以观察的问题。</p><p>开始时分开记录三个角色：使用者、决定是否采用的人、付款的人。个体经营者可能兼任三者；在团队里，使用者觉得方便，并不表示负责人同意付费。再写出最可能让计划失败的一条假设，例如“整理工作足够频繁，值得单独购买服务”。</p><p>先寻找做过这项任务的人，包括继续手工做、使用现成工具和已经放弃尝试的人。熟人容易接触，但应标明关系；只采访热心朋友，不能解释陌生用户是否需要。记录邀请人数、回应人数和拒绝原因，不把没有回应的人算成认可。</p><h2 id="_2-询问过去的行为" tabindex="-1">2. 询问过去的行为 <a class="header-anchor" href="#_2-询问过去的行为" aria-label="Permalink to &quot;2. 询问过去的行为&quot;">​</a></h2><p>访谈的目标是重建一次真实过程，不是说服对方称赞创意。可从这些问题开始：</p><ol><li>最近一次做这件事是什么时候，是什么触发了它？</li><li>能按顺序讲讲从接到任务到完成都做了什么吗？</li><li>哪一步需要等待、返工或找别人帮助？能提供一个不含私人信息的例子吗？</li><li>目前用什么办法，为什么仍在使用？试过哪些办法又放弃了？</li><li>谁认定任务完成，谁决定是否花钱，下一次何时还会发生？</li></ol><p>先取得记录同意，不需要的信息不收集；不同意录音就记摘要。未经许可，不上传聊天记录或客户材料给 AI。把笔记分为“对方原话”“观察到的行为”“自己的解释”，不要把自己的解释放进引号里。</p><p>“这个功能你会买吗”得到的是一种预测；“上次为解决它做了什么”更接近已经发生的行为。对方说“很麻烦”，还需要追问频率和后果。也主动问：什么时候这件事根本不值得解决？什么情况下现有办法已经足够？</p><h2 id="_3-和现有办法比较" tabindex="-1">3. 和现有办法比较 <a class="header-anchor" href="#_3-和现有办法比较" aria-label="Permalink to &quot;3. 和现有办法比较&quot;">​</a></h2><p>替代方案不只包括同类产品，也包括手工、外包、少做一次、推迟和不做。给每种办法写下完成结果、全部耗时、直接支出、出错后的处理，以及换用新办法需要谁配合。</p><table tabindex="0"><thead><tr><th>观察</th><th>可以支持的判断</th><th>暂时不能支持的判断</th></tr></thead><tbody><tr><td>说“听起来不错”</td><td>愿意继续交流</td><td>愿意使用或付款</td></tr><tr><td>展示最近的工作样例</td><td>任务发生过</td><td>任务足够频繁</td></tr><tr><td>安排下一次试做并提供可用材料</td><td>愿意投入时间测试</td><td>新流程胜过原流程</td></tr><tr><td>按明确范围付款并完成验收</td><td>这一次交换得到接受</td><td>稳定需求或可盈利</td></tr><tr><td>在类似条件下再次购买</td><td>出现了重复需求的信号</td><td>更大人群都愿意购买</td></tr></tbody></table><p>这是整理证据的工作表，不是通用评分模型。记录反例同样重要：有人只在旺季需要，有人更信任熟悉的模板，有人切换流程比继续手工还麻烦。不要把这些人自动归类为“不懂产品”。</p><h2 id="_4-用人工试点检验结果" tabindex="-1">4. 用人工试点检验结果 <a class="header-anchor" href="#_4-用人工试点检验结果" aria-label="Permalink to &quot;4. 用人工试点检验结果&quot;">​</a></h2><p>在自动化之前，可以先用人工完成一个很窄的服务。明确告诉参与者哪些由人完成、哪些由工具辅助，不把人工操作展示为已有的自动化能力。</p><p>例如，只整理一批由经营者确认的商品资料，交付草稿和待确认问题，不代替对方发布。约定输入要求、数量、完成日期、包含几轮修改、验收方式及撤回办法。无法取得必要授权或无法避免敏感材料时，换成公开样例，或停止这一试点。</p><p>保存原流程的基线，再记录新流程里双方的全部工作：准备材料、沟通、制作、核对、修改和等待。服务方省下的时间，如果变成用户额外核对的时间，就不能直接宣称节省。AI 项目还可结合 <a href="./../part-3/2-ai-development-and-resource-layer">开发与资源层创业</a> 检查数据、能力和交付边界。</p><p>付费试点应提前讲清价格、交付和退出安排，不能用隐藏收费或夸大效果制造“付款证据”。免费试用适合观察流程是否可用；它没有检验那个价格是否被接受。折扣、熟人关系和额外陪伴也要记录，因为下一次交易可能不再有这些条件。</p><h2 id="_5-把两周安排成一个问题" tabindex="-1">5. 把两周安排成一个问题 <a class="header-anchor" href="#_5-把两周安排成一个问题" aria-label="Permalink to &quot;5. 把两周安排成一个问题&quot;">​</a></h2><p>两周只是便于设限的工作周期，招募或采购流程更长时，应另定合理期限。以下是一轮示例：</p><ul><li><strong>第 1–2 天</strong>：写一个主要假设、可接受投入上限、目标人群和预先约定的判定条件。</li><li><strong>第 3–5 天</strong>：访谈并还原最近任务，寻找不需要此服务的反例，整理现有办法。</li><li><strong>第 6–7 天</strong>：向符合条件的人提出同一范围的试点，记录价格、拒绝原因和下一步安排。</li><li><strong>第 8–11 天</strong>：交付少量试点，记录质量、双方时间、支出和返工。</li><li><strong>第 12–14 天</strong>：按事先写下的条件判读，留下仍未知的问题和下一轮唯一改动。</li></ul><p>假设本轮计划访谈 6 位经营者，最多投入 12 小时，只判断“是否值得再做一轮付费验证”。事先约定：至少 3 人能展示近期重复任务，至少 2 人接受明确价格的试点，并在约定范围内完成验收。这个门槛是团队的工作选择，不是市场验证标准；即使达到，也只支持再投入一小步。</p><h2 id="_6-允许结论是调整或停止" tabindex="-1">6. 允许结论是调整或停止 <a class="header-anchor" href="#_6-允许结论是调整或停止" aria-label="Permalink to &quot;6. 允许结论是调整或停止&quot;">​</a></h2><p>如果 6 人中 4 人有近期任务，2 人付款，但其中 1 单严重超出交付工时，可以得出“存在初步付费信号，交付成本尚未成立”。不能写成“产品已验证”。下一轮可以缩小输入范围并测量返工，不必立刻招人或增加功能。</p><ul><li><strong>继续</strong>：事先条件满足，投入未超限；保留有效范围，只扩大一点样本或观察重复购买。</li><li><strong>调整</strong>：有需要但流程、范围或价格假设不成立；下一轮只改一个主要变量，说明为什么。</li><li><strong>停止或暂缓</strong>：核心条件未满足、无法触达目标人群，或投入已到上限；结清承诺，记录重启需要的新证据。</li></ul><p>样本不足时，结论是“证据不足”，不是成功，也不必包装成失败。无论哪种结论，都写下“什么新事实会让我改变判断”。把决定落在 <a href="./../../templates/startup-experiment">创业实验卡</a> 上，再用 <a href="./sustainable-business">可持续的小生意</a> 检查交付与成本。</p><h2 id="用英语说清这次实验" tabindex="-1">用英语说清这次实验 <a class="header-anchor" href="#用英语说清这次实验" aria-label="Permalink to &quot;用英语说清这次实验&quot;">​</a></h2><p>尝试用四句话向同伴汇报，保留数字和不确定性，不把“有人感兴趣”翻译成 “validated demand”：</p><blockquote><p>We tested whether shop owners would pay for a narrowly scoped service. Two people paid for a pilot, but one delivery exceeded our time limit. This suggests some willingness to pay; it does not establish a sustainable business. Next, we will test a smaller scope and track revision time.</p></blockquote><p>关键词：<strong>customer discovery</strong>（了解用户问题）、<strong>current workaround</strong>（现有应对办法）、<strong>willingness to pay</strong>（付费意愿）、<strong>disconfirming evidence</strong>（不支持假设的证据）。</p>',33)])])}const m=e(s,[["render",i]]);export{u as __pageData,m as default};
